3	import (
4		"context"
5		"errors"
6		"fmt"
7		"os/exec"
8		"sort"
9		"strings"
10		"sync"
11		"time"
12	
13		"github.com/entireio/cli/cmd/entire/cli/auth"
14		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
15		"github.com/entireio/cli/cmd/entire/cli/gitrepo"
16		"github.com/entireio/cli/cmd/entire/cli/logging"
17		"github.com/entireio/cli/cmd/entire/cli/paths"
18		"github.com/entireio/cli/cmd/entire/cli/search"
19		"github.com/entireio/cli/cmd/entire/cli/trailers"
20		"github.com/go-git/go-git/v6"
21		"github.com/go-git/go-git/v6/plumbing"
22		"golang.org/x/sync/errgroup"
23	)
24	
25	var (
26		// lookupResourceToken returns a bearer scoped to the given resource
27		// origin. Production wiring goes through auth.TokenForResource so
28		// the tokenmanager's same-host shortcut, JWT-aud shortcut, and
29		// exchange dispatch all apply. Tests swap to a fixed-token closure.
30		lookupResourceToken = auth.TokenForResource
31	
32		nowUTC = func() time.Time { return time.Now().UTC() }
33	)
34	
35	func runLocal(ctx context.Context, opts Options) (*Dispatch, error) {
36		now := nowUTC()
37		sinceInput := strings.TrimSpace(opts.Since)
38		if sinceInput == "" {
39			sinceInput = "7d"
40		}
41		since, err := ParseSinceAtNow(sinceInput, now)
42		if err != nil {
43			return nil, err
44		}
45		until, err := ParseUntilAtNow(opts.Until, now)
46		if err != nil {
47			return nil, err
48		}
49		normalizedSince, normalizedUntil := NormalizeWindow(since, until)
50		if !normalizedSince.Before(normalizedUntil) {
51			return nil, errors.New("--since must be before --until")
52		}
53	
54		repoRoots, err := resolveRepoRoots(ctx, opts.RepoPaths)
55		if err != nil {
56			return nil, err
57		}
58	
59		allCandidates := make([]candidate, 0)
60		var candidatesMu sync.Mutex
61		group, groupCtx := errgroup.WithContext(ctx)
62		for _, repoRoot := range repoRoots {
63			group.Go(func() error {
64				candidates, err := enumerateRepoCandidates(groupCtx, repoRoot, opts, normalizedSince, normalizedUntil)
65				if err != nil {
66					return err
67				}
68				candidatesMu.Lock()
69				allCandidates = append(allCandidates, candidates...)
70				candidatesMu.Unlock()
71				return nil
72			})
73		}
74		if err := group.Wait(); err != nil {
75			return nil, fmt.Errorf("enumerate repo candidates: %w", err)
76		}
77	
78		fallback := applyFallbackChain(allCandidates)
79		dispatch := &Dispatch{
80			CoveredRepos: coveredRepos(allCandidates),
81			Repos:        groupBulletsByRepo(fallback.Used),
82			Window: Window{
83				NormalizedSince:   normalizedSince,
84				NormalizedUntil:   normalizedUntil,
85				FirstCheckpointAt: firstAt(fallback.Used),
86				LastCheckpointAt:  lastAt(fallback.Used),
87			},
88		}
89	
90		text, err := generateLocalDispatch(ctx, dispatch, opts.Voice)
91		if err != nil {
92			return nil, err
93		}
94		if strings.TrimSpace(text) == "" {
95			return nil, errDispatchMissingMarkdown
96		}
97		dispatch.GeneratedText = text
98	
99		return dispatch, nil
100	}
101	
102	func NormalizeWindow(since, until time.Time) (time.Time, time.Time) {
103		floored := since.Truncate(time.Minute)
104		ceiled := until.Truncate(time.Minute)
105		if !until.Equal(ceiled) {
106			ceiled = ceiled.Add(time.Minute)
107		}
108		return floored, ceiled
109	}
110	
111	func resolveRepoRoots(ctx context.Context, repoPaths []string) ([]string, error) {
112		if len(repoPaths) == 0 {
113			repoRoot, err := paths.WorktreeRoot(ctx)
114			if err != nil {
115				return nil, fmt.Errorf("not in a git repository: %w", err)
116			}
117			return []string{repoRoot}, nil
118		}
119	
120		roots := make([]string, 0, len(repoPaths))
121		for _, repoPath := range repoPaths {
122			cmd := exec.CommandContext(ctx, "git", "-C", repoPath, "rev-parse", "--show-toplevel")
123			output, err := cmd.Output()
124			if err != nil {
125				return nil, fmt.Errorf("resolve repo root for %q: %w", repoPath, err)
126			}
127			roots = append(roots, strings.TrimSpace(string(output)))
128		}
129		return roots, nil
130	}
131	
132	func enumerateRepoCandidates(ctx context.Context, repoRoot string, opts Options, since, until time.Time) ([]candidate, error) {
133		repo, err := gitrepo.OpenPath(repoRoot)
134		if err != nil {
135			return nil, fmt.Errorf("open repository %s: %w", repoRoot, err)
136		}
137		defer repo.Close()
138	
139		repoFullName, err := resolveRepoFullName(ctx, repo)
140		if err != nil {
141			return nil, fmt.Errorf("resolve repo name for %s: %w", repoRoot, err)
142		}
143	
144		branches := opts.Branches
145		switch {
146		case opts.AllBranches:
147			branches, err = localBranchNames(repo)
148			if err != nil {
149				return nil, err
150			}
151		case len(branches) == 0:
152			currentBranch, err := currentBranchName(repo)
153			if err != nil {
154				return nil, err
155			}
156			branches = []string{currentBranch}
157		}
158		branchSet := make(map[string]struct{}, len(branches))
159		for _, branch := range branches {
160			branchSet[branch] = struct{}{}
161		}
162		reachableCheckpointIDs := map[string]struct{}{}
163		if opts.ImplicitCurrentBranch && !opts.AllBranches {
164			reachableCheckpointIDs, err = reachableCheckpointIDsInRange(ctx, repoRoot, branchLocalRevRange(ctx, repoRoot), since)
165			if err != nil {
166				return nil, err
167			}
168		}
169		commitSubjectsByCheckpoint, err := loadCommitSubjectsByCheckpoint(ctx, repoRoot, since)
170		if err != nil {
171			return nil, err
172		}
173	
174		checkpoint.SyncCommittedReadRef(ctx, repo)
175		store := checkpoint.NewCommittedReadStore(ctx, repo)
176		infos, err := store.ListCommitted(ctx)
177		if err != nil {
178			return nil, fmt.Errorf("list committed checkpoints: %w", err)
179		}
180	
181		candidates := make([]candidate, 0, len(infos))
182		for _, info := range infos {
183			if info.CreatedAt.Before(since) || !info.CreatedAt.Before(until) {
184				continue
185			}
186	
187			summary, err := store.ReadCommitted(ctx, info.CheckpointID)
188			if err != nil {
189				logging.Warn(ctx, "failed to read committed checkpoint for dispatch", "checkpoint_id", info.CheckpointID.String(), "error", err)
190				continue
191			}
192			if summary == nil {
193				continue
194			}
195			if _, onSelectedBranch := branchSet[summary.Branch]; !onSelectedBranch {
196				if !opts.ImplicitCurrentBranch {
197					continue
198				}
199				if _, reachable := reachableCheckpointIDs[info.CheckpointID.String()]; !reachable {
200					continue
201				}
202			}
203	
204			localSummary := ""
205			if len(summary.Sessions) > 0 {
206				latestIndex := len(summary.Sessions) - 1
207				if metadata, err := store.ReadSessionMetadata(ctx, info.CheckpointID, latestIndex); err == nil && metadata != nil && metadata.Summary != nil {
208					localSummary = strings.TrimSpace(metadata.Summary.Outcome)
209					if localSummary == "" {
210						localSummary = strings.TrimSpace(metadata.Summary.Intent)
211					}
212				}
213			}
214	
215			commitSubject := commitSubjectsByCheckpoint[info.CheckpointID.String()]
216			candidates = append(candidates, candidate{
217				CheckpointID:      info.CheckpointID.String(),
218				RepoFullName:      repoFullName,
219				Branch:            summary.Branch,
220				CreatedAt:         info.CreatedAt,
221				CommitSubject:     commitSubject,
222				LocalSummaryTitle: localSummary,
223			})
224		}
225	
226		return candidates, nil
227	}
228	
229	func reachableCheckpointIDsInRange(ctx context.Context, repoRoot, revRange string, since time.Time) (map[string]struct{}, error) {
230		cmd := exec.CommandContext(
231			ctx,
232			"git",
233			"-C",
234			repoRoot,
235			"log",
236			revRange,
237			"--since="+since.UTC().Format(time.RFC3339),
238			"--grep",
239			"Entire-Checkpoint:",
240			"--format=%B%x00",
241		)
242		output, err := cmd.Output()
243		if err != nil {
244			return nil, fmt.Errorf("list HEAD checkpoint trailers: %w", err)
245		}
246	
247		reachable := make(map[string]struct{})
248		for _, message := range strings.Split(string(output), "\x00") {
249			for _, checkpointID := range trailers.ParseAllCheckpoints(message) {
250				reachable[checkpointID.String()] = struct{}{}
251			}
252		}
253		return reachable, nil
254	}
255	
256	// branchLocalRevRange returns a git log rev range that limits commits to
257	// those unique to the current branch — reachable from HEAD but not from the
258	// repository's default branch. Falls back to "HEAD" when no default branch
259	// can be resolved (e.g. a fresh repo with no main/master ref).
260	func branchLocalRevRange(ctx context.Context, repoRoot string) string {
261		base := defaultBranchRef(ctx, repoRoot)
262		if base == "" {
263			return "HEAD"
264		}
265		return base + "..HEAD"
266	}
267	
268	// defaultBranchRef resolves the repository's default branch, preferring
269	// origin/HEAD and falling back to the conventional main/master names. A
270	// candidate is only accepted if it is an ancestor of HEAD — otherwise a
271	// repo with an unconventional default (e.g. develop, trunk) would silently
272	// exclude the wrong history. Returns an empty string if nothing matches so
273	// callers can skip the exclusion.
274	func defaultBranchRef(ctx context.Context, repoRoot string) string {
275		if out, ok := runGitOutput(ctx, repoRoot, "symbolic-ref", "--quiet", "refs/remotes/origin/HEAD"); ok {
276			ref := strings.TrimSpace(out)
277			if strings.HasPrefix(ref, "refs/remotes/") {
278				candidate := strings.TrimPrefix(ref, "refs/remotes/")
279				if isAncestorOfHEAD(ctx, repoRoot, candidate) {
280					return candidate
281				}
282			}
283		}
284		for _, candidate := range []string{"origin/main", "origin/master", "main", "master"} {
285			if _, ok := runGitOutput(ctx, repoRoot, "rev-parse", "--verify", "--quiet", candidate); !ok {
286				continue
287			}
288			if isAncestorOfHEAD(ctx, repoRoot, candidate) {
289				return candidate
290			}
291		}
292		return ""
293	}
294	
295	func isAncestorOfHEAD(ctx context.Context, repoRoot, ref string) bool {
296		_, ok := runGitOutput(ctx, repoRoot, "merge-base", "--is-ancestor", ref, "HEAD")
297		return ok
298	}
299	
300	func runGitOutput(ctx context.Context, repoRoot string, args ...string) (string, bool) {
301		fullArgs := append([]string{"-C", repoRoot}, args...)
302		out, err := exec.CommandContext(ctx, "git", fullArgs...).Output()
303		if err != nil {
304			return "", false
305		}
306		return string(out), true
307	}
308	
309	func resolveRepoFullName(ctx context.Context, repo *git.Repository) (string, error) {
310		remote, err := repo.Remote("origin")
311		if err != nil {
312			logging.Warn(ctx, "dispatch repo resolution failed", "step", "origin_remote", "error", err)
313			return "", fmt.Errorf("dispatch currently supports GitHub repositories with an origin remote: %w", err)
314		}
315		if len(remote.Config().URLs) == 0 {
316			return "", errors.New("dispatch currently supports GitHub repositories with an origin remote URL")
317		}
318	
319		owner, repoName, err := search.ParseGitHubRemote(remote.Config().URLs[0])
320		if err != nil {
321			logging.Warn(ctx, "dispatch repo resolution failed", "step", "parse_origin_remote", "error", err)
322			return "", fmt.Errorf("dispatch currently supports GitHub origin remotes only: %w", err)
323		}
324		return owner + "/" + repoName, nil
325	}
326	
327	func currentBranchName(repo *git.Repository) (string, error) {
328		head, err := repo.Head()
329		if err != nil {
330			return "", fmt.Errorf("get HEAD: %w", err)
331		}
332		if !head.Name().IsBranch() {
333			return "", errors.New("not on a branch (detached HEAD)")
334		}
335		return head.Name().Short(), nil
336	}
337	
338	// localBranchNames returns the short names of the user's local branches,
339	// omitting the reserved "entire/" namespace used for internal refs.
340	func localBranchNames(repo *git.Repository) ([]string, error) {
341		iter, err := repo.Branches()
342		if err != nil {
343			return nil, fmt.Errorf("list local branches: %w", err)
344		}
345		defer iter.Close()
346	
347		var names []string
348		if err := iter.ForEach(func(ref *plumbing.Reference) error {
349			name := ref.Name().Short()
350			if strings.HasPrefix(name, checkpoint.ShadowBranchPrefix) {
351				return nil
352			}
353			names = append(names, name)
354			return nil
355		}); err != nil {
356			return nil, fmt.Errorf("iterate local branches: %w", err)
357		}
358		sort.Strings(names)
359		return names, nil
360	}
361	
362	func loadCommitSubjectsByCheckpoint(ctx context.Context, repoRoot string, since time.Time) (map[string]string, error) {
363		cmd := exec.CommandContext(
364			ctx,
365			"git",
366			"-C",
367			repoRoot,
368			"log",
369			"--all",
370			"--since="+since.UTC().Format(time.RFC3339),
371			"--grep",
372			"Entire-Checkpoint:",
373			"--format=%s%x00%B%x00%x00",
374		)
375		output, err := cmd.Output()
376		if err != nil {
377			return nil, fmt.Errorf("git log --grep: %w", err)
378		}
379	
380		subjects := make(map[string]string)
381		for _, record := range strings.Split(string(output), "\x00\x00") {
382			record = strings.TrimSuffix(record, "\x00")
383			if record == "" {
384				continue
385			}
386			parts := strings.SplitN(record, "\x00", 2)
387			if len(parts) != 2 {
388				continue
389			}
390			subject := strings.TrimSpace(parts[0])
391			for _, checkpointID := range trailers.ParseAllCheckpoints(parts[1]) {
392				id := checkpointID.String()
393				if _, ok := subjects[id]; ok {
394					continue
395				}
396				subjects[id] = subject
397			}
398		}
399		return subjects, nil
400	}
401	
402	func coveredRepos(candidates []candidate) []string {
403		if len(candidates) == 0 {
404			return nil
405		}
406	
407		repoSet := make(map[string]struct{}, len(candidates))
408		for _, candidate := range candidates {
409			if candidate.RepoFullName == "" {
410				continue
411			}
412			repoSet[candidate.RepoFullName] = struct{}{}
413		}
414	
415		repos := make([]string, 0, len(repoSet))
416		for repoFullName := range repoSet {
417			repos = append(repos, repoFullName)
418		}
419		sort.Strings(repos)
420		return repos
421	}
422	
423	func groupBulletsByRepo(used []repoBullet) []RepoGroup {
424		repoMap := make(map[string]map[string][]Bullet)
425		for _, item := range used {
426			if _, ok := repoMap[item.RepoFullName]; !ok {
427				repoMap[item.RepoFullName] = make(map[string][]Bullet)
428			}
429			label := "Updates"
430			if len(item.Bullet.Labels) > 0 && strings.TrimSpace(item.Bullet.Labels[0]) != "" {
431				label = item.Bullet.Labels[0]
432			}
433			repoMap[item.RepoFullName][label] = append(repoMap[item.RepoFullName][label], item.Bullet)
434		}
435	
436		repoNames := make([]string, 0, len(repoMap))
437		for repoName := range repoMap {
438			repoNames = append(repoNames, repoName)
439		}
440		sort.Strings(repoNames)
441	
442		out := make([]RepoGroup, 0, len(repoNames))
443		for _, repoName := range repoNames {
444			sectionMap := repoMap[repoName]
445			labels := make([]string, 0, len(sectionMap))
446			for label := range sectionMap {
447				labels = append(labels, label)
448			}
449			sort.Strings(labels)
450	
451			sections := make([]Section, 0, len(labels))
452			for _, label := range labels {
453				sections = append(sections, Section{
454					Label:   label,
455					Bullets: sectionMap[label],
456				})
457			}
458			out = append(out, RepoGroup{
459				FullName: repoName,
460				URL:      githubRepoURL(repoName),
461				Sections: sections,
462			})
463		}
464	
465		return out
466	}
467	
468	func firstAt(used []repoBullet) time.Time {
469		var first time.Time
470		for _, item := range used {
471			if item.Bullet.CreatedAt.IsZero() {
472				continue
473			}
474			if first.IsZero() || item.Bullet.CreatedAt.Before(first) {
475				first = item.Bullet.CreatedAt
476			}
477		}
478		return first
479	}
480	
481	func lastAt(used []repoBullet) time.Time {
482		var last time.Time
483		for _, item := range used {
484			if item.Bullet.CreatedAt.After(last) {
485				last = item.Bullet.CreatedAt
486			}
487		}
488		return last
489	}
