1	package checkpoint
2	
3	import (
4		"context"
5		"errors"
6		"log/slog"
7	
8		"github.com/go-git/go-git/v6"
9		"github.com/go-git/go-git/v6/plumbing"
10	
11		"github.com/entireio/cli/cmd/entire/cli/logging"
12	)
13	
14	// NewCommittedReadStore returns a GitStore bound to the topology's read ref.
15	func NewCommittedReadStore(ctx context.Context, repo *git.Repository) *GitStore {
16		return NewGitStoreWithRef(repo, ResolveCommittedRefs(ctx).Read)
17	}
18	
19	// SyncCommittedReadRef advances the mirror ref to the primary tip before a read
20	// so a git pull (which updates the primary but not the local-only mirror) is
21	// reflected. No-op without a mirror. Best-effort.
22	func SyncCommittedReadRef(ctx context.Context, repo *git.Repository) {
23		refs := ResolveCommittedRefs(ctx)
24		if !refs.HasMirror() {
25			return
26		}
27		syncMirrorForRead(ctx, repo, refs)
28	}
29	
30	// syncMirrorForRead advances the mirror ref to the primary tip (local primary
31	// ref, or origin's on a fresh clone): seed when missing, advance when an
32	// ancestor, no-op when equal, leave a diverged ref as-is. Failures are logged.
33	func syncMirrorForRead(ctx context.Context, repo *git.Repository, refs CommittedRefs) {
34		primaryHash, ok := resolvePrimaryTip(repo, refs.Primary)
35		if !ok {
36			logging.Debug(ctx, "mirror read sync skipped: no primary tip available")
37			return
38		}
39	
40		mirrorRefName := refs.Mirror
41		mirrorRef, err := repo.Reference(mirrorRefName, false)
42		if errors.Is(err, plumbing.ErrReferenceNotFound) {
43			setMirrorRef(ctx, repo, mirrorRefName, primaryHash) // missing — seed at primary tip
44			return
45		}
46		if err != nil {
47			// Unexpected read error — don't overwrite the ref; read it as-is.
48			logging.Warn(ctx, "mirror read sync skipped: mirror ref unreadable",
49				slog.String("ref", mirrorRefName.String()),
50				slog.String("error", err.Error()))
51			return
52		}
53	
54		if mirrorRef.Hash() == primaryHash {
55			return // already current
56		}
57	
58		mirrorCommit, err := repo.CommitObject(mirrorRef.Hash())
59		if err != nil {
60			logging.Warn(ctx, "mirror read sync skipped: mirror ref commit unreadable",
61				slog.String("ref", mirrorRefName.String()),
62				slog.String("error", err.Error()))
63			return
64		}
65		primaryCommit, err := repo.CommitObject(primaryHash)
66		if err != nil {
67			logging.Warn(ctx, "mirror read sync skipped: primary commit unreadable",
68				slog.String("error", err.Error()))
69			return
70		}
71	
72		isAncestor, err := mirrorCommit.IsAncestor(primaryCommit)
73		if err != nil {
74			logging.Warn(ctx, "mirror read sync skipped: ancestry check failed",
75				slog.String("error", err.Error()))
76			return
77		}
78		if !isAncestor {
79			// Diverged from the primary: leave the ref untouched and read it as-is.
80			logging.Warn(ctx, "mirror ref diverged from primary; reading mirror ref as-is",
81				slog.String("ref", mirrorRefName.String()),
82				slog.String("mirror_hash", mirrorRef.Hash().String()),
83				slog.String("primary_hash", primaryHash.String()))
84			return
85		}
86	
87		setMirrorRef(ctx, repo, mirrorRefName, primaryHash)
88	}
89	
90	// resolvePrimaryTip returns the primary metadata tip, preferring the local
91	// primary ref and falling back to origin's remote-tracking branch (so the
92	// mirror can seed on a fresh clone).
93	func resolvePrimaryTip(repo *git.Repository, primary plumbing.ReferenceName) (plumbing.Hash, bool) {
94		if ref, err := repo.Reference(primary, true); err == nil {
95			return ref.Hash(), true
96		}
97		if primary.IsBranch() {
98			tracking := plumbing.NewRemoteReferenceName("origin", primary.Short())
99			if ref, err := repo.Reference(tracking, true); err == nil {
100				return ref.Hash(), true
101			}
102		}
103		return plumbing.ZeroHash, false
104	}
105	
106	// setMirrorRef points refName at hash; failures are logged and swallowed so the
107	// read can proceed against the ref as-is.
108	func setMirrorRef(ctx context.Context, repo *git.Repository, refName plumbing.ReferenceName, hash plumbing.Hash) {
109		if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, hash)); err != nil {
110			logging.Warn(ctx, "mirror read sync failed to advance mirror ref",
111				slog.String("ref", refName.String()),
112				slog.String("error", err.Error()))
